import { expect, expectStatus, test } from "../../fixtures";

test.describe("sign in", () => {
  test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
    // Arrange: a member who is signed in
    const member = await apiAs("member");
    await expectStatus(await member.get("/api/me"), 200);

    // Act: the member signs out
    const response = await member.post("/api/auth/logout");

    // Assert: 204 with no body, and the session cookie is cleared
    await expectStatus(response, 204);
    const cookie = response
      .headersArray()
      .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
    expect(cookie, "a Set-Cookie header for the session cookie").toBeDefined();
    const value = cookie?.value.toLowerCase() ?? "";
    expect(value.startsWith('session=""') || value.includes("max-age=0")).toBe(true);
  });
});
